  ),
  Question(
    id: "pfrh_q260",
    topicId: "pfrh_t2",
    text: r"""¿Cuál es el valor filosófico y jurídico fundamental sobre el cual se erigen e interpretan todos los Derechos Humanos?""",
    options: [
      r"""Seguridad del Estado""",
      r"""Libertad individual""",
      r"""Bien común colectivo""",
      r"""Propiedad privada""",
      r"""Dignidad humana""",
