      r"""Debe izarse obligatoriamente en el asta principal de las plazas públicas al igual que el Pabellón Nacional.""",
      r"""Es de uso exclusivo del Presidente de la República y de los magistrados del Tribunal Constitucional por decreto supremo.""",
