  ),
  Question(
    id: "pfrh_q717",
    topicId: "pfrh_t5",
    text: r"""Cuando la estructura familiar acoge, además de los padres e hijos, a otros parientes como abuelos, tíos, primos o sobrinos que cohabitan en el mismo hogar, se trata de una:""",
    options: [
      r"""Familia ensamblada""",
