  ),
  Question(
    id: "pfrh_q776",
    topicId: "pfrh_t6",
    text: r"""¿Cuál de los siguientes principios de la Ley N° 30364 exige que las intervenciones estatales consideren las diferencias culturales y las lenguas originarias de las víctimas?""",
