  Question(
    id: "pfrh_q777",
    topicId: "pfrh_t6",
    text: r"""Según el marco de la Ley N° 30364, ¿qué entidad tiene la responsabilidad de ejecutar de manera inmediata las medidas de protección que prohíben el acercamiento del agresor a la víctima?""",
    options: [
